// Formal checker for the approved credit_counter RTL (credit_counter.v).
// Each property is tagged with the interface_spec.md requirement it checks.
// The only environment constraint is reset in the first cycle; take, give and
// rst_n are otherwise unconstrained at every cycle.
`timescale 1ns / 1ps

module credit_counter_fv #(
    parameter integer MAX = 4
) (
    input wire clk,
    input wire rst_n,
    input wire take,
    input wire give
);
    localparam [7:0] F_MAX = MAX;

    wire [7:0] credits;
    wire       avail;
    wire       full;
    wire       err;

    credit_counter #(.MAX(MAX)) dut (
        .clk(clk),
        .rst_n(rst_n),
        .take(take),
        .give(give),
        .credits(credits),
        .avail(avail),
        .full(full),
        .err(err)
    );

    reg f_past_valid = 1'b0;
    always @(posedge clk) f_past_valid <= 1'b1;

    // Environment: reset is applied in the first cycle (minimal constraint).
    always @(*) begin
        if (!f_past_valid) begin
            assume (!rst_n);
        end
    end

    wire f_take_only = take && !give;
    wire f_give_only = give && !take;
    wire f_refuse    = (f_take_only && (credits == 8'd0))
                    || (f_give_only && (credits == F_MAX));

    // [req:CC-STATUS] status outputs follow credits combinationally.
    // [req:CC-RANGE]  credits never above MAX once reset has been applied.
    always @(*) begin
        a_status_avail: assert (avail == (credits != 8'd0));
        a_status_full:  assert (full == (credits == F_MAX));
        if (f_past_valid) begin
            a_range: assert (credits <= F_MAX);
        end
    end

    always @(posedge clk) begin
        if (f_past_valid) begin
            if (!$past(rst_n)) begin
                // [req:CC-RESET]
                a_reset_credits: assert (credits == F_MAX);
                a_reset_err:     assert (!err);
            end else begin
                // [req:CC-TAKE]
                if ($past(f_take_only) && ($past(credits) != 8'd0)) begin
                    a_take: assert (credits == ($past(credits) - 8'd1));
                end
                // [req:CC-GIVE]
                if ($past(f_give_only) && ($past(credits) != F_MAX)) begin
                    a_give: assert (credits == ($past(credits) + 8'd1));
                end
                // [req:CC-BOTH]
                if ($past(take) && $past(give)) begin
                    a_both: assert (credits == $past(credits));
                end
                // [req:CC-IDLE]
                if (!$past(take) && !$past(give)) begin
                    a_idle: assert (credits == $past(credits));
                end
                // [req:CC-UNDERFLOW]
                if ($past(f_take_only) && ($past(credits) == 8'd0)) begin
                    a_underflow: assert ((credits == 8'd0) && err);
                end
                // [req:CC-OVERFLOW]
                if ($past(f_give_only) && ($past(credits) == F_MAX)) begin
                    a_overflow: assert ((credits == F_MAX) && err);
                end
                // [req:CC-ERR-STICKY]
                if ($past(err)) begin
                    a_err_sticky: assert (err);
                end
                // err port: high only once a take or give has been refused;
                // [req:CC-BOTH] nothing is refused when both are high.
                if (!$past(f_refuse)) begin
                    a_err_no_spurious: assert (err == $past(err));
                end
            end
        end
    end

    // Covers: one per assertion antecedent, so no pass is vacuous.
    always @(posedge clk) begin
        if (f_past_valid) begin
            c_reset:                   cover (!$past(rst_n));
            c_reset_clears_err:        cover (!$past(rst_n) && $past(err));
            c_take:                    cover ($past(rst_n) && $past(f_take_only) && ($past(credits) != 8'd0));
            c_give:                    cover ($past(rst_n) && $past(f_give_only) && ($past(credits) != F_MAX));
            c_both_zero:               cover ($past(rst_n) && $past(take) && $past(give) && ($past(credits) == 8'd0));
            c_both_max:                cover ($past(rst_n) && $past(take) && $past(give) && ($past(credits) == F_MAX));
            c_idle:                    cover ($past(rst_n) && !$past(take) && !$past(give));
            c_underflow:               cover ($past(rst_n) && $past(f_take_only) && ($past(credits) == 8'd0));
            c_overflow:                cover ($past(rst_n) && $past(f_give_only) && ($past(credits) == F_MAX));
            c_err_sticky:              cover ($past(rst_n) && $past(err));
            c_err_held_while_counting: cover ($past(rst_n) && $past(err) && err && (credits != $past(credits)));
            c_err_no_spurious:         cover ($past(rst_n) && !$past(f_refuse) && !$past(err));
            c_empty:                   cover (!avail);
            c_full:                    cover (full);
        end
    end
endmodule

// Top: the checker at several MAX values, each with independent free inputs.
module credit_counter_fv_top (
    input wire clk,
    input wire rst_n_m1,
    input wire take_m1,
    input wire give_m1,
    input wire rst_n_m4,
    input wire take_m4,
    input wire give_m4,
    input wire rst_n_m5,
    input wire take_m5,
    input wire give_m5
);
    credit_counter_fv #(.MAX(1)) u_max1 (
        .clk(clk), .rst_n(rst_n_m1), .take(take_m1), .give(give_m1)
    );

    credit_counter_fv #(.MAX(4)) u_max4 (
        .clk(clk), .rst_n(rst_n_m4), .take(take_m4), .give(give_m4)
    );

    credit_counter_fv #(.MAX(5)) u_max5 (
        .clk(clk), .rst_n(rst_n_m5), .take(take_m5), .give(give_m5)
    );
endmodule
