// Formal checker for the approved credit_counter RTL (credit_counter.v).
// Each property is tagged in a comment with the interface_spec.md requirement
// it checks. Statement labels are deliberately not used: the Yosys
// read -formal front end rejects them.
// The only environment constraint is reset in the first cycle; take, give and
// rst_n are otherwise unconstrained at every cycle.
`timescale 1ns / 1ps

module credit_counter_fv #(
    parameter integer MAX = 4
) (
    input wire clk,
    input wire rst_n,
    input wire take,
    input wire give
);
    localparam [7:0] F_MAX = MAX;

    wire [7:0] credits;
    wire       avail;
    wire       full;
    wire       err;

    credit_counter #(.MAX(MAX)) dut (
        .clk(clk),
        .rst_n(rst_n),
        .take(take),
        .give(give),
        .credits(credits),
        .avail(avail),
        .full(full),
        .err(err)
    );

    reg f_past_valid = 1'b0;
    always @(posedge clk) f_past_valid <= 1'b1;

    // Environment: reset is applied in the first cycle (minimal constraint).
    always @(*) begin
        if (!f_past_valid) begin
            assume (!rst_n);
        end
    end

    wire f_take_only = take && !give;
    wire f_give_only = give && !take;
    wire f_refuse    = (f_take_only && (credits == 8'd0))
                    || (f_give_only && (credits == F_MAX));

    always @(*) begin
        // [req:CC-STATUS] avail follows credits combinationally.
        assert (avail == (credits != 8'd0));
        // [req:CC-STATUS] full follows credits combinationally.
        assert (full == (credits == F_MAX));
        if (f_past_valid) begin
            // [req:CC-RANGE] credits never above MAX once reset has been applied.
            assert (credits <= F_MAX);
        end
    end

    always @(posedge clk) begin
        if (f_past_valid) begin
            if (!$past(rst_n)) begin
                // [req:CC-RESET] credits loads MAX.
                assert (credits == F_MAX);
                // [req:CC-RESET] err clears.
                assert (!err);
            end else begin
                // [req:CC-TAKE]
                if ($past(f_take_only) && ($past(credits) != 8'd0)) begin
                    assert (credits == ($past(credits) - 8'd1));
                end
                // [req:CC-GIVE]
                if ($past(f_give_only) && ($past(credits) != F_MAX)) begin
                    assert (credits == ($past(credits) + 8'd1));
                end
                // [req:CC-BOTH]
                if ($past(take) && $past(give)) begin
                    assert (credits == $past(credits));
                end
                // [req:CC-IDLE]
                if (!$past(take) && !$past(give)) begin
                    assert (credits == $past(credits));
                end
                // [req:CC-UNDERFLOW]
                if ($past(f_take_only) && ($past(credits) == 8'd0)) begin
                    assert ((credits == 8'd0) && err);
                end
                // [req:CC-OVERFLOW]
                if ($past(f_give_only) && ($past(credits) == F_MAX)) begin
                    assert ((credits == F_MAX) && err);
                end
                // [req:CC-ERR-STICKY]
                if ($past(err)) begin
                    assert (err);
                end
                // err port: high only once a take or give has been refused;
                // [req:CC-BOTH] nothing is refused when both are high.
                if (!$past(f_refuse)) begin
                    assert (err == $past(err));
                end
            end
        end
    end

    // Covers: one per assertion antecedent, so no pass is vacuous.
    always @(posedge clk) begin
        if (f_past_valid) begin
            // reset antecedent
            cover (!$past(rst_n));
            // reset clears a set err
            cover (!$past(rst_n) && $past(err));
            // take antecedent
            cover ($past(rst_n) && $past(f_take_only) && ($past(credits) != 8'd0));
            // give antecedent
            cover ($past(rst_n) && $past(f_give_only) && ($past(credits) != F_MAX));
            // both at zero
            cover ($past(rst_n) && $past(take) && $past(give) && ($past(credits) == 8'd0));
            // both at MAX
            cover ($past(rst_n) && $past(take) && $past(give) && ($past(credits) == F_MAX));
            // idle antecedent
            cover ($past(rst_n) && !$past(take) && !$past(give));
            // underflow antecedent
            cover ($past(rst_n) && $past(f_take_only) && ($past(credits) == 8'd0));
            // overflow antecedent
            cover ($past(rst_n) && $past(f_give_only) && ($past(credits) == F_MAX));
            // sticky err antecedent
            cover ($past(rst_n) && $past(err));
            // err held while credits change
            cover ($past(rst_n) && $past(err) && err && (credits != $past(credits)));
            // no-spurious-err antecedent with err clear
            cover ($past(rst_n) && !$past(f_refuse) && !$past(err));
            // status: empty
            cover (!avail);
            // status: full
            cover (full);
        end
    end
endmodule

// Top: the checker at several MAX values, each with independent free inputs.
module credit_counter_fv_top (
    input wire clk,
    input wire rst_n_m1,
    input wire take_m1,
    input wire give_m1,
    input wire rst_n_m4,
    input wire take_m4,
    input wire give_m4,
    input wire rst_n_m5,
    input wire take_m5,
    input wire give_m5
);
    credit_counter_fv #(.MAX(1)) u_max1 (
        .clk(clk), .rst_n(rst_n_m1), .take(take_m1), .give(give_m1)
    );

    credit_counter_fv #(.MAX(4)) u_max4 (
        .clk(clk), .rst_n(rst_n_m4), .take(take_m4), .give(give_m4)
    );

    credit_counter_fv #(.MAX(5)) u_max5 (
        .clk(clk), .rst_n(rst_n_m5), .take(take_m5), .give(give_m5)
    );
endmodule
